import java.io.*;
import java.nio.file.Path;

public class ConfigLoader {
    public byte[] loadConfig(Path configPath) throws IOException {
        // try-with-resources ensures streams close automatically
        try (var fileInput = new FileInputStream(configPath.toFile());
             var buffered = new BufferedInputStream(fileInput)) {

            var output = new ByteArrayOutputStream();
            var buffer = new byte[8192]; // 8KB buffer for efficiency
            int bytesRead;

            // read() returns -1 when stream ends
            while ((bytesRead = buffered.read(buffer)) != -1) {
                output.write(buffer, 0, bytesRead);
            }

            return output.toByteArray();
        }
    }
}

