import java.io.*;
import java.nio.file.*;

public class FileCopier {
    // Manual approach with full control
    public void copyWithStreams(Path source, Path target) throws IOException {
        try (var fileIn = new FileInputStream(source.toFile());
             var buffIn = new BufferedInputStream(fileIn);
             var fileOut = new FileOutputStream(target.toFile());
             var buffOut = new BufferedOutputStream(fileOut)) {

            var buffer = new byte[8192];
            int bytesRead;
            // read returns -1 when stream ends
            while ((bytesRead = buffIn.read(buffer)) != -1) {
                buffOut.write(buffer, 0, bytesRead); // write exact count
            }
        } // streams auto-close here
    }

    // Modern approach for production
    public void copyWithNIO(Path source, Path target) throws IOException {
        Files.copy(source, target, StandardCopyOption.REPLACE_EXISTING);
    }
}

import java.io.*;
import java.nio.file.*;

public class FileByteReader {
    private static final long MAX_DIRECT_READ = 10 * 1024 * 1024; // 10MB

    public byte[] readFile(Path filePath) throws IOException {
        long fileSize = Files.size(filePath);

        if (fileSize <= MAX_DIRECT_READ) {
            // Simple approach for small files
            return Files.readAllBytes(filePath);
        } else {
            // Stream approach for large files
            return readLargeFile(filePath);
        }
    }

    private byte[] readLargeFile(Path filePath) throws IOException {
        try (var fileIn = new FileInputStream(filePath.toFile());
             var buffered = new BufferedInputStream(fileIn)) {

            var output = new ByteArrayOutputStream();
            var buffer = new byte[8192];
            int bytesRead;

            while ((bytesRead = buffered.read(buffer)) != -1) {
                output.write(buffer, 0, bytesRead);
            }
            return output.toByteArray();
        }
    }
}

import java.io.*;
import java.util.List;

record Order(Long id, String item, double price) implements Serializable {}

public class OrderSerializer {
    public byte[] serialize(Order order) throws IOException {
        var byteOutput = new ByteArrayOutputStream();
        // ObjectOutputStream wraps our in-memory stream
        try (var objectOutput = new ObjectOutputStream(byteOutput)) {
            objectOutput.writeObject(order);
            objectOutput.flush(); // ensure all data written
        }
        return byteOutput.toByteArray(); // get result as byte array
    }

    // Testing without any files
    public static void main(String[] args) throws IOException, ClassNotFoundException {
        var serializer = new OrderSerializer();
        var order = new Order(123L, "Laptop", 999.99);

        byte[] bytes = serializer.serialize(order);
        System.out.println("Serialized to " + bytes.length + " bytes");
    }
}

import java.io.*;
import java.nio.file.Path;
import java.time.Instant;

record LogEntry(int level, Instant timestamp, String message) {}

public class BinaryLogReader {
    public LogEntry readEntry(Path logFile) throws IOException {
        try (var fileIn = new FileInputStream(logFile.toFile());
             var buffered = new BufferedInputStream(fileIn);
             var dataIn = new DataInputStream(buffered)) {

            // Read in exact order written by DataOutputStream
            int level = dataIn.readInt();           // 4 bytes
            long epochMillis = dataIn.readLong();   // 8 bytes
            String message = dataIn.readUTF();      // length-prefixed string

            var timestamp = Instant.ofEpochMilli(epochMillis);
            return new LogEntry(level, timestamp, message);
        }
    }
}
